import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

# Define a fused CUDA kernel that applies Leaky ReLU and then does x + x (equivalent to multiplying by 2)
fused_source = r"""
#include <torch/extension.h>
#include <cuda_runtime.h>

__global__ void fused_leaky_relu_and_sum_kernel(
    const float* __restrict__ in_data,
    float* __restrict__ out_data,
    float negative_slope,
    int size
) {
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    if (idx < size) {
        float val = in_data[idx];
        if (val < 0.0f) {
            val *= negative_slope;
        }
        // x = x + x => 2 * x
        out_data[idx] = 2.0f * val;
    }
}

torch::Tensor fused_leaky_relu_and_sum_cuda(torch::Tensor x, float negative_slope) {
    auto out = torch::empty_like(x);
    int size = x.numel();
    int blockSize = 256;
    int gridSize = (size + blockSize - 1) / blockSize;

    fused_leaky_relu_and_sum_kernel<<<gridSize, blockSize>>>(
        x.data_ptr<float>(),
        out.data_ptr<float>(),
        negative_slope,
        size
    );

    return out;
}
"""

fused_header = "torch::Tensor fused_leaky_relu_and_sum_cuda(torch::Tensor x, float negative_slope);"

# Build the fused operator
fused_ops = load_inline(
    name="fused_leaky_relu_and_sum",
    cpp_sources=fused_header,
    cuda_sources=fused_source,
    functions=["fused_leaky_relu_and_sum_cuda"],
    verbose=False
)

class ModelNew(nn.Module):
    """
    A model that performs a matrix multiplication, group normalization,
    and a fused Leaky ReLU + element-wise sum.
    """
    def __init__(self, input_size, hidden_size, num_groups, eps=1e-5, negative_slope=0.01):
        super(ModelNew, self).__init__()
        self.fc = nn.Linear(input_size, hidden_size)
        self.gn = nn.GroupNorm(num_groups=num_groups, num_channels=hidden_size, eps=eps)
        self.negative_slope = negative_slope

    def forward(self, x):
        # Matrix multiplication
        x = self.fc(x)
        # Group normalization
        x = self.gn(x)
        # Fused Leaky ReLU + x + x
        x = fused_ops.fused_leaky_relu_and_sum_cuda(x, self.negative_slope)
        return x

batch_size = 128
input_size = 512
hidden_size = 256
num_groups = 8

def get_inputs():
    return [torch.randn(batch_size, input_size).cuda()]

def get_init_inputs():
    return [input_size, hidden_size, num_groups]
